  }
}
GROUP BY ?italianLemma ?italianWord
HAVING (COUNT(DISTINCT ?emotion) > 6)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?italianWord ?polarityValue
WHERE {
  {
    SELECT (MAX(?refVal) AS ?refPolarityValue)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?refLemma a ?refLemmaType ;
                  ontolex:writtenRep ?refWord .
        FILTER(?refLemmaType IN (lila:Lemma, lila:Hypolemma))
        FILTER(STR(?refWord) = "appartenenza")
      }
      ?refPolarityEntry ontolex:canonicalForm ?refLemma ;
                        marl:hasPolarity ?refPolarity ;
                        marl:hasPolarityValue ?refVal .
    }
  }

  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  lila:hasPOS lila:noun ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Fiducia .
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .

  FILTER(xsd:float(?polarityValue) > xsd:float(?refPolarityValue))
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?italianWord) AS ?count)
WHERE {
  {
    GRAPH <http://liita.it/data> {
      ?italianLemma a ?italianLemmaType ;
                    ontolex:writtenRep ?italianWord .
      FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    }
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion elita:Disgusto .
    }
  }
  UNION
  {
    GRAPH <http://liita.it/data> {
      ?italianLemma a ?italianLemmaType ;
                    ontolex:writtenRep ?italianWord .
      FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    }
    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .
    FILTER(xsd:float(?polarityValue) < -0.9)
  }
}

