PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?otherWord ?sicilianWord
WHERE {
  # Find 'allegria' and its Sicilian translation
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?italianWord) = "allegria")
  }

  ?italianEntry ontolex:canonicalForm ?italianLemma ;
                vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .

  # Find other Italian words translating to the same Sicilian word
  GRAPH <http://liita.it/data> {
    ?otherLemma a ?otherLemmaType ;
                ontolex:writtenRep ?otherWord .
    FILTER(?otherLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?otherEntry ontolex:canonicalForm ?otherLemma ;
              vartrans:translatableAs ?otherSicilianLexEntry .
  ?otherSicilianLexEntry ontolex:canonicalForm ?otherSicilianLemma .
  ?otherSicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                       ontolex:writtenRep ?otherSicilianWord .

  # Same Sicilian translation
  FILTER(STR(?otherSicilianWord) = STR(?sicilianWord))
  # Exclude 'allegria' itself
  FILTER(?otherLemma != ?italianLemma)
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?otherWord ?sicilianWord
WHERE {
  # Reference word: 'ansia'
  GRAPH <http://liita.it/data> {
    ?ansiaLemma a ?ansiaLemmaType ;
                ontolex:writtenRep ?ansiaWord .
    FILTER(?ansiaLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER(STR(?ansiaWord) = "ansia")
  }

  # Sicilian translation of 'ansia'
  ?ansiaEntry ontolex:canonicalForm ?ansiaLemma ;
              vartrans:translatableAs ?sicEntry .
  ?sicEntry ontolex:canonicalForm ?sicLemma .
  ?sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
            ontolex:writtenRep ?sicilianWord .

  # Other Italian words
  GRAPH <http://liita.it/data> {
    ?otherLemma a ?otherLemmaType ;
                ontolex:writtenRep ?otherWord .
    FILTER(?otherLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Their Sicilian translation
  ?otherEntry ontolex:canonicalForm ?otherLemma ;
              vartrans:translatableAs ?otherSicEntry .
  ?otherSicEntry ontolex:canonicalForm ?otherSicLemma .
  ?otherSicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?otherSicilianWord .

  # Same Sicilian word, different Italian word
  FILTER(STR(?otherSicilianWord) = STR(?sicilianWord))
  FILTER(?otherLemma != ?ansiaLemma)
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
