    ?hyponymWord ontolex:sense ?hyponymSense .
  }
  ?hyponymWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER NOT EXISTS {
    ?sicItEntry ontolex:canonicalForm ?italianLemma ;
                vartrans:translatableAs ?sicEntry .
    ?sicEntry ontolex:canonicalForm ?sicLemma .
    ?sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?sicilianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:verb .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER regex(str(?italianWord), "^sc", "i")

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  FILTER regex(str(?sicilianWord), "^sc", "i")
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?sentixPolarity ?elitaPolarity ?sentixValue ?elitaValue
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:adverb .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?sentixPolarity ;
                 marl:hasPolarityValue ?sentixValue .

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry marl:Polarity ?elitaPolarity ;
                  marl:hasPolarityValue ?elitaValue .
  }

  FILTER(
    (?sentixPolarity = marl:Positive && STR(?elitaPolarity) = "Negative") ||
    (?sentixPolarity = marl:Negative && STR(?elitaPolarity) = "Positive")
  )
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?sicilianWord (COUNT(DISTINCT ?italianWord) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:verb .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
}
GROUP BY ?sicilianWord
HAVING (COUNT(DISTINCT ?italianWord) > 6)
ORDER BY DESC(?count)

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (AVG(?emotionCount) AS ?avgEmotionsPerAdjective)
WHERE {
  {
    SELECT ?italianLemma (COUNT(DISTINCT ?emotion) AS ?emotionCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      lila:hasPOS lila:adjective ;
                      ontolex:writtenRep ?italianWord .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    GROUP BY ?italianLemma
    HAVING (COUNT(DISTINCT ?emotion) >= 1)
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  {
    SELECT (MAX(?studiarePolarityValue) AS ?maxStudiareValue)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?studiareLemma a ?studiareLemmaType ;
                       ontolex:writtenRep ?studiareWord ;
                       lila:hasPOS lila:verb .
        FILTER(?studiareLemmaType IN (lila:Lemma, lila:Hypolemma))
        FILTER(STR(?studiareWord) = "studiare")
      }
      ?studiarePolarityEntry ontolex:canonicalForm ?studiareLemma ;
                             marl:hasPolarity ?studiarePolarity ;
                             marl:hasPolarityValue ?studiarePolarityValue .
    }
  }
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord ;
                  lila:hasPOS lila:verb .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .
  FILTER(?polarityValue > ?maxStudiareValue)
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?emotionLabel ?count
WHERE {
  {
    SELECT ?emotion ?emotionLabel (COUNT(DISTINCT ?italianLemma) AS ?count)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      lila:hasPOS lila:verb ;
                      ontolex:writtenRep ?italianWord .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
      }
    }
    GROUP BY ?emotion ?emotionLabel
  }
  {
    SELECT (COUNT(DISTINCT ?sadLemma) AS ?sadnessCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?sadLemma a ?sadLemmaType ;
                  lila:hasPOS lila:verb .
        FILTER(?sadLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?sadEmotionEntry ontolex:canonicalForm ?sadLemma .
      GRAPH <http://w3id.org/elita> {
        ?sadEmotionEntry elita:HasEmotion elita:Tristezza .
      }
    }
  }
  FILTER(?count > ?sadnessCount)
}
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?dialect ?dialectWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  FILTER(REGEX(STR(?italianWord), "^sv", "i"))

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?dialectLexEntry .
  ?dialectLexEntry ontolex:canonicalForm ?dialectLemma .
  ?dialectLemma ontolex:writtenRep ?dialectWord .

  {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    BIND("Sicilian" AS ?dialect)
  } UNION {
    ?dialectLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    BIND("Parmigiano" AS ?dialect)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?dialect ?dialectWord
WHERE {
  # Find kinds of mammal (hyponyms of "mammifero") in CompL-it
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?mammiferoWord ontolex:canonicalForm [ ontolex:writtenRep ?mammiferoWr ] .
    FILTER(STR(?mammiferoWr) = "mammifero")
    ?mammiferoWord ontolex:sense ?mammiferoSense .
    ?mammiferoSense lexinfo:hypernym ?resultSense .
    ?resultWord ontolex:sense ?resultSense ;
                ontolex:canonicalForm [ ontolex:writtenRep ?resultWr ] .
  }

  # Link to LiIta lemma
  ?resultWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  # Translations in Sicilian OR Parmigiano
  {
    ?italianSicilianLexEntry ontolex:canonicalForm ?italianLemma .
    ?italianSicilianLexEntry vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?dialectWord .
    BIND("Sicilian" AS ?dialect)
  } UNION {
    ?italianParmigianoLexEntry ontolex:canonicalForm ?italianLemma .
    ?italianParmigianoLexEntry vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?dialectWord .
    BIND("Parmigiano" AS ?dialect)
  }
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?italianWord
       (SAMPLE(?definition) AS ?definition)
       (COUNT(DISTINCT ?emotion) AS ?emotionCount)
       (MAX(?polarityValue) AS ?maxPolarityValue)
       (SAMPLE(?sicilianWord) AS ?sicilianWord)
       (SAMPLE(?parmigianoWord) AS ?parmigianoWord)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense ?sense ;
          ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    ?sense skos:definition ?definition .
    FILTER(REGEX(STR(?definition), "dolore", "i"))
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
                  ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
  }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarity ?polarity ;
                 marl:hasPolarityValue ?polarityValue .
  ?italianSicilianEntry ontolex:canonicalForm ?italianLemma ;
                        vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWord .
  ?italianParmigianoEntry ontolex:canonicalForm ?italianLemma ;
                          vartrans:translatableAs ?parmigianoLexEntry .
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?parmigianoWord .
}
GROUP BY ?italianWord

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?emotionLabel
       (COUNT(DISTINCT ?posLemma) AS ?positiveCount)
       (COUNT(DISTINCT ?negLemma) AS ?negativeCount)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  {
    SELECT ?italianLemma (AVG(xsd:float(?polarityValue)) AS ?avgPolarityValue)
    WHERE {
      ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                     marl:hasPolarity ?polarity ;
                     marl:hasPolarityValue ?polarityValue .
    }
    GROUP BY ?italianLemma
  }

  OPTIONAL {
    FILTER(?avgPolarityValue > 0)
    BIND(?italianLemma AS ?posLemma)
  }
  OPTIONAL {
    FILTER(?avgPolarityValue < 0)
    BIND(?italianLemma AS ?negLemma)
  }
}
GROUP BY ?emotionLabel

# Words with Tristezza in ELIta and a positive Sentix polarity, with the polarity value.
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord ?polarityValue
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?emotionEntry ontolex:canonicalForm ?lemma ;
      elita:HasEmotion elita:Tristezza .
  ?polarityEntry ontolex:canonicalForm ?lemma ;
      marl:hasPolarity marl:Positive ;
      marl:hasPolarityValue ?polarityValue .
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?category (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }

  {
    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity .
    FILTER NOT EXISTS {
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    BIND("Sentix polarity but no ELIta emotion" AS ?category)
  }
  UNION
  {
    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
      ?emotionEntry elita:HasEmotion ?emotion .
    }
    FILTER NOT EXISTS {
      ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                     marl:hasPolarity ?polarity .
    }
    BIND("ELIta emotion but no Sentix polarity" AS ?category)
  }
}
GROUP BY ?category

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT 
  ?totalEmotionLemmas 
  ?sicilianCount 
  ?parmigianoCount 
  (?sicilianCount * 1.0 / ?totalEmotionLemmas AS ?sicilianShare)
  (?parmigianoCount * 1.0 / ?totalEmotionLemmas AS ?parmigianoShare)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?italianLemma) AS ?totalEmotionLemmas)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?italianLemma) AS ?sicilianCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
      ?italianSicilianEntry ontolex:canonicalForm ?italianLemma ;
                            vartrans:translatableAs ?sicilianLexEntry .
      ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
      ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?italianLemma) AS ?parmigianoCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }
      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
      ?italianParmigianoEntry ontolex:canonicalForm ?italianLemma ;
                              vartrans:translatableAs ?parmigianoLexEntry .
      ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
      ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> .
    }
  }
}

PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?senseGroup (COUNT(DISTINCT ?italianLemma) AS ?numAdjectives) (AVG(?emotionCount) AS ?avgEmotions)
WHERE {
  {
    SELECT ?italianLemma (COUNT(DISTINCT ?sense) AS ?count) (COUNT(DISTINCT ?emotion) AS ?emotionCount)
    WHERE {
      GRAPH <http://liita.it/data> {
        ?italianLemma a ?italianLemmaType ;
                      lila:hasPOS lila:adjective ;
                      ontolex:writtenRep ?italianWord .
        FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
      }

      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:canonicalForm [ ontolex:writtenRep ?italianWord ] ;
              ontolex:sense ?sense .
      }
      ?word ontolex:canonicalForm ?italianLemma .

      ?emotionEntry ontolex:canonicalForm ?italianLemma .
      GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
      }
    }
    GROUP BY ?italianLemma
  }

  BIND(IF(?count = 1, "one_sense", "more_than_one_sense") AS ?senseGroup)
}
GROUP BY ?senseGroup
